\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

\definecolor{primary}{HTML}{0D1B2A}
\definecolor{secondary}{HTML}{F4A261}
\definecolor{accent}{HTML}{E63946}
\definecolor{bgposter}{HTML}{0D1B2A}
\definecolor{redbg}{HTML}{1A2332}
\definecolor{bluebg}{HTML}{1A2840}
\definecolor{goldbg}{HTML}{1F2A1E}
\definecolor{ambertitle}{HTML}{2A1F0A}
\definecolor{redtitlebg}{HTML}{2A1010}
\definecolor{bluetitlebg}{HTML}{0A1A2A}
\definecolor{textwhite}{HTML}{FDF6E3}
\definecolor{textlight}{HTML}{A8DADC}
\definecolor{stathighlight}{HTML}{2A1F10}
\definecolor{creamtext}{HTML}{F4A261}

\pagecolor{bgposter}
\color{textwhite}

\setlist[itemize]{leftmargin=20pt, itemsep=4pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}

\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{22}{28}\selectfont\color{textlight}\textit{#3}}\vspace{2mm}%
}

\tcbset{
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=ambertitle,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.25},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={6pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.25},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={6pt}{0pt}{textlight},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={textlight!50},
    valign=top, drop shadow={opacity=0.25},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% TITLE BAR
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries\textcolor{textwhite}{Malaria: A Preventable Killer}}
  \\[10pt]
  {\fontsize{34}{42}\selectfont\textcolor{secondary}{Global Progress and the Road Ahead}}
  \\[6pt]
  {\fontsize{24}{30}\selectfont\textcolor{textlight!70}{Source: WHO Global Malaria Report, IHME Global Burden of Disease}}
}

% HERO STAT
\posterbox[
  enhanced, colback={1A0505}, colframe=accent, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=20pt, right=20pt, top=8pt, bottom=8pt,
  halign=center, valign=center,
  borderline={4pt}{0pt}{accent!60},
  drop shadow={opacity=0.4}
]{name=herostat, column=1, span=3, between=row4 and row8}{
  \centering
  {\fontsize{26}{32}\selectfont\textcolor{accent!80}{EVERY DAY, CHILDREN DIE FROM A DISEASE WE KNOW HOW TO PREVENT}}
  \\[8pt]
  {\fontsize{130}{156}\selectfont\bfseries\textcolor{accent}{1,320}}
  \\[4pt]
  {\fontsize{48}{58}\selectfont\bfseries\textcolor{textwhite}{children die every single day}}
  \\[6pt]
  {\fontsize{26}{32}\selectfont\textcolor{textlight}{That's one child every 65 seconds --- and it is preventable.}}
}

% BURDEN (col 1)
\posterbox[redcard, title={The Burden: Who Malaria Kills}
]{name=burden, column=1, between=row8 and row14}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}
    \item \textbf{500,000+} people die each year
    \item \textbf{Africa} bears 95\% of the global burden
    \item \textbf{Children under 5} are most vulnerable
  \end{itemize}
  \\[6pt]
  \colorbox{accent!22}{\parbox{0.92\linewidth}{%
    \centering
    {\fontsize{28}{36}\selectfont\bfseries\textcolor{accent}{500K+}}
    {\fontsize{22}{28}\selectfont\textcolor{textlight}{ deaths/year}}
  }}
  \\[8pt]
  \colorbox{accent!15}{\parbox{0.92\linewidth}{%
    \centering
    {\fontsize{26}{34}\selectfont\textcolor{textlight}{In the 2010s, malaria killed more than half a million people annually --- most of them young children.}}
  }}
  \\[6pt]
  \fontsize{26}{34}\selectfont\textcolor{textlight}{
    Sub-Saharan Africa: 95\% of all malaria cases and deaths occur here, yet the disease was once eliminated across Europe and North America.}
}

% HISTORICAL PROGRESS (col 2)
\posterbox[goldcard, title={From Half the World to a Quarter}
]{name=progress, column=2, between=row8 and row14}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}
    \item Malaria once covered \textbf{~50\%} of Earth's land
    \item By 2002, shrank to \textbf{~27\%} --- nearly halved
    \item Eliminated from Europe, East Asia, Australia
  \end{itemize}
  \\[4pt]
  \posterfig{0.95}{figures/coverage.png}{Malaria risk area: ~50\% of land (~1900) to ~27\% (2002)}
  \\[4pt]
  \fontsize{24}{32}\selectfont\textcolor{secondary}{
    Key drivers: insecticides, land drainage, economic development}
}

% DEATH TOLL TRENDS (col 3)
\posterbox[bluecard, title={Death Toll Trends: 2000-2023}
]{name=trends, column=3, between=row8 and row14}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}
    \item \textbf{2000-2015}: Steady decline (863K to 535K)
    \item \textbf{2015-2019}: Progress stalling
    \item \textbf{2020}: COVID-19 disruption reversed gains
  \end{itemize}
  \\[4pt]
  \posterfig{0.95}{figures/death_trends.png}{Global malaria deaths in thousands (WHO estimates)}
  \\[4pt]
  \fontsize{24}{32}\selectfont\textcolor{textlight}{
    38\% drop in deaths from 2000 to 2019 --- but 2020 saw the first increase in decades.}
}

% INTERVENTIONS (col 1-2, rows 14-18)
\posterbox[goldcard, title={What Works: Tools to Beat Malaria}
]{name=interventions, column=1, span=2, between=row14 and row18}{
  \fontsize{28}{38}\selectfont
  \begin{itemize}
    \item \textbf{Insecticide-treated bednets} --- one of the most cost-effective tools
    \item \textbf{Malaria vaccines} --- new vaccines offer promising additional protection
    \item \textbf{Indoor residual spraying} --- targets mosquito habitats directly
    \item \textbf{Economic development} --- better housing and healthcare access
  \end{itemize}
  \\[6pt]
  \centering
  \includegraphics[width=0.55\linewidth]{figures/interventions.png}\\[3mm]
  {\fontsize{20}{26}\selectfont\color{textlight}\textit{Cost-effectiveness of malaria interventions}}
}

% AFRICA STATS (col 3)
\posterbox[redcard, title={Africa: The Front Line}
]{name=africa, column=3, between=row14 and row18}{
  \fontsize{28}{38}\selectfont
  \colorbox{accent!18}{\parbox{0.90\linewidth}{%
    \centering
    {\fontsize{64}{78}\selectfont\bfseries\textcolor{accent}{95\%}}
    {\fontsize{26}{34}\selectfont\textcolor{textlight}{ of global\\ malaria deaths}}
  }}
  \\[10pt]
  \fontsize{26}{34}\selectfont\textcolor{textlight}{
    Yet malaria was once endemic in England, Italy, Greece, the southern US, and Japan. Elimination is possible.}
}

% CTA (full width, bottom)
\posterbox[
  enhanced, colback=primary, colframe=secondary, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=24pt, right=24pt, top=6pt, bottom=6pt,
  halign=center, valign=center,
  borderline south={4pt}{0pt}{secondary!60},
  drop shadow={opacity=0.35}
]{name=cta, column=1, span=3, between=row18 and bottom}{
  \centering
  {\fontsize{28}{36}\selectfont\textcolor{secondary}{\textbf{The Solution Exists. The Question Is Will.}}
  \hspace{20pt}
  {\fontsize{28}{36}\selectfont\textcolor{textlight}{
    Invest in bednets. Support vaccine rollout. Fund global health.}}
  \hspace{20pt}
  {\fontsize{28}{36}\selectfont\textcolor{accent}{\textbf{1,320 children today. Will we act?}}
}

\end{tcbposter}
\end{document}

